mapper.select:
select * from( SELECT fa.fd_filing_id,f.fd_car_no,fa.fd_filing_factory_code, FA.fd_filing_factory,FA.fd_filing_begin,FA.fd_filing_end, FA.create_time,FA.approve_code,FA.approve_name, FP.fd_per_name,FP.fd_per_phone,f.fd_supplier_name,f.fd_goods_name,ep.fd_driver_name, ENTER2.token_no,ENTER2.tcm_name,ENTER2.staff_no,ENTER2.staff_name,ENTER2.in_time, ENTER2.in_lane_name,ENTER2.in_operator_name,ENTER2.out_time,ENTER2.out_lane_name, ENTER2.out_operator_name,ENTER2.stay_lasts,ENTER2.in_picture,ENTER2.out_picture, case when ENTER2.in_status is null then '未入厂' else ENTER2.in_status end in_status FROM safety_enter_filing_approve fa INNER join safety_enter_filing f on fa.fd_filing_id = f.id INNER JOIN safety_enter_filing_per FP ON FP.filing_id = F.ID AND FP.fd_per_type_code = '10' INNER JOIN safety_enter_protect EP ON EP.fd_car_no = f.fd_car_no INNER JOIN (SELECT max(fa.create_time) create_time,f.fd_car_no FROM safety_enter_filing_approve fa INNER JOIN safety_enter_filing f on fa.fd_filing_id = f.id WHERE 1 = 1
GROUP BY fd_car_no) ENTER1 ON fa.create_time = ENTER1.create_time AND f.fd_car_no = ENTER1.fd_car_no LEFT JOIN (SELECT h1.token_no,h1.tcm_name,h1.staff_no,h1.staff_name,h1.in_time, h1.in_lane_name,h1.in_operator_name,h1.out_time,h1.out_lane_name, h1.out_operator_name,h1.stay_lasts,h1.in_picture,h1.out_picture, case when h1.out_time is null then '在厂' else '已离厂' end in_status FROM safety_crk_car_out_history h1 INNER JOIN (SELECT token_no,max(in_time) in_time FROM safety_crk_car_out_history GROUP BY token_no) h2 on h1.token_no = h2.token_no and h1.in_time = h2.in_time WHERE 1 = 1) ENTER2 ON F.fd_car_no = ENTER2.token_no WHERE 1 = 1 ) enter3 WHERE 1 = 1
limit #{offset}, #{limit}
limit #{limit}
limit 5000

SELECT count(1)
 from safety_enter_filing ef,
      safety_enter_filing_approve ea
where ef.fd_state_code in (30,31)
  and ea.fd_filing_id = ef.id

  and ea.approve_code = #{isAdmin}


  and ef.fd_filing_end >= #{fdFilingBegin}
  and ef.fd_filing_begin < #{fdFilingEnd}

SELECT count(1) enter_car_num,sum(car_num) enter_total_num
from( SELECT ef.fd_car_no,count(1) car_num
        from safety_crk_car_out_history ch,
             safety_enter_filing ef,
             safety_enter_filing_approve ea
       where ch.token_no = ef.fd_car_no
         and ea.fd_filing_id = ef.id

  and ea.approve_code = #{isAdmin}

         and ef.fd_state_code in (30,31)

         and ef.fd_filing_end >= #{fdFilingBegin}
         and ef.fd_filing_begin < #{fdFilingEnd}
         and ch.in_time >= #{fdFilingBegin}
         and ch.in_time < #{fdFilingEnd}

       GROUP BY ef.fd_car_no) enter_tem

select * from( SELECT fa.fd_filing_id,f.fd_car_no,fa.fd_filing_factory_code, FA.fd_filing_factory,FA.fd_filing_begin,FA.fd_filing_end, FA.create_time,FA.approve_code,FA.approve_name, FP.fd_per_name,FP.fd_per_phone,f.fd_supplier_name,f.fd_goods_name,ep.fd_driver_name, ENTER2.token_no,ENTER2.tcm_name,ENTER2.staff_no,ENTER2.staff_name,ENTER2.in_time, ENTER2.in_lane_name,ENTER2.in_operator_name,ENTER2.out_time,ENTER2.out_lane_name, ENTER2.out_operator_name,ENTER2.stay_lasts,ENTER2.in_picture,ENTER2.out_picture, ENTER2.fn as in_factory, case when ENTER2.in_status is null then '未入厂' else ENTER2.in_status end in_status FROM safety_enter_filing_approve fa INNER join safety_enter_filing f on fa.fd_filing_id = f.id INNER JOIN safety_enter_filing_per FP ON FP.filing_id = F.ID AND FP.fd_per_type_code = '10' INNER JOIN safety_enter_protect EP ON EP.fd_car_no = f.fd_car_no INNER JOIN ( SELECT max(fa.create_time) create_time,f.fd_car_no FROM safety_enter_filing_approve fa INNER JOIN safety_enter_filing f on fa.fd_filing_id = f.id
GROUP BY fd_car_no ) ENTER1 ON fa.create_time = ENTER1.create_time AND f.fd_car_no = ENTER1.fd_car_no LEFT JOIN ( SELECT h1.token_no,h1.tcm_name,h1.staff_no,h1.staff_name,h1.in_time, h1.in_lane_name,h1.in_operator_name,h1.out_time,h1.out_lane_name, h1.out_operator_name,h1.stay_lasts,h1.in_picture,h1.out_picture, r.factory_name as fn, case when h1.out_time is null or h1.out_time = '' then '在厂' else '已离厂' end in_status FROM safety_crk_car_out_history h1 left join safety_gate_factory_relation r on h1.in_operator_name = r.gate_name
h1.id in
#{item}
h1.id = 0
) ENTER2 ON f.fd_car_no = ENTER2.token_no where
fa.fd_filing_begin <= now() and fa.fd_filing_end >= now()
) enter3
limit #{offset}, #{limit}
limit #{limit}
limit 5000

select count(1) from( SELECT fa.fd_filing_id,f.fd_car_no,fa.fd_filing_factory_code, FA.fd_filing_factory,FA.fd_filing_begin,FA.fd_filing_end, FA.create_time,FA.approve_code,FA.approve_name, FP.fd_per_name,FP.fd_per_phone,f.fd_supplier_name,f.fd_goods_name,ep.fd_driver_name, ENTER2.token_no,ENTER2.tcm_name,ENTER2.staff_no,ENTER2.staff_name,ENTER2.in_time, ENTER2.in_lane_name,ENTER2.in_operator_name,ENTER2.out_time,ENTER2.out_lane_name, ENTER2.out_operator_name,ENTER2.stay_lasts,ENTER2.in_picture,ENTER2.out_picture, case when ENTER2.in_status is null then '未入厂' else ENTER2.in_status end in_status FROM safety_enter_filing_approve fa INNER join safety_enter_filing f on fa.fd_filing_id = f.id INNER JOIN safety_enter_filing_per FP ON FP.filing_id = F.ID AND FP.fd_per_type_code = '10' INNER JOIN safety_enter_protect EP ON EP.fd_car_no = f.fd_car_no INNER JOIN ( SELECT max(fa.create_time) create_time,f.fd_car_no FROM safety_enter_filing_approve fa INNER JOIN safety_enter_filing f on fa.fd_filing_id = f.id
GROUP BY fd_car_no ) ENTER1 ON fa.create_time = ENTER1.create_time AND f.fd_car_no = ENTER1.fd_car_no LEFT JOIN ( SELECT h1.token_no,h1.tcm_name,h1.staff_no,h1.staff_name,h1.in_time, h1.in_lane_name,h1.in_operator_name,h1.out_time,h1.out_lane_name, h1.out_operator_name,h1.stay_lasts,h1.in_picture,h1.out_picture, case when h1.out_time is null or h1.out_time = '' then '在厂' else '已离厂' end in_status FROM safety_crk_car_out_history h1
h1.id in
#{item}
h1.id = 0
) ENTER2 ON f.fd_car_no = ENTER2.token_no where
fa.fd_filing_begin <= now() and fa.fd_filing_end >= now()
) enter3

select * from( SELECT fa.fd_filing_id,f.fd_car_no,fa.fd_filing_factory_code, FA.fd_filing_factory,FA.fd_filing_begin,FA.fd_filing_end, FA.create_time,FA.approve_code,FA.approve_name, FP.fd_per_name,FP.fd_per_phone,f.fd_supplier_name,f.fd_goods_name,ep.fd_driver_name, ENTER2.token_no,ENTER2.tcm_name,ENTER2.staff_no,ENTER2.staff_name,ENTER2.in_time, ENTER2.in_lane_name,ENTER2.in_operator_name,ENTER2.out_time,ENTER2.out_lane_name, ENTER2.out_operator_name,ENTER2.stay_lasts,ENTER2.in_picture,ENTER2.out_picture, ENTER2.fn as in_factory, ENTER2.in_status as in_status FROM safety_enter_filing_approve fa INNER join safety_enter_filing f on fa.fd_filing_id = f.id INNER JOIN safety_enter_filing_per FP ON FP.filing_id = F.ID AND FP.fd_per_type_code = '10' INNER JOIN safety_enter_protect EP ON EP.fd_car_no = f.fd_car_no INNER JOIN ( SELECT max(fa.create_time) create_time,f.fd_car_no FROM safety_enter_filing_approve fa INNER JOIN safety_enter_filing f on fa.fd_filing_id = f.id
GROUP BY fd_car_no ) ENTER1 ON fa.create_time = ENTER1.create_time AND f.fd_car_no = ENTER1.fd_car_no LEFT JOIN ( SELECT h1.token_no,h1.tcm_name,h1.staff_no,h1.staff_name,h1.in_time, h1.in_lane_name,h1.in_operator_name,h1.out_time,h1.out_lane_name, h1.out_operator_name,h1.stay_lasts,h1.in_picture,h1.out_picture, r.factory_name as fn, '已出厂' as in_status FROM safety_crk_car_out_history h1 left join safety_gate_factory_relation r on h1.in_operator_name = r.gate_name where h1.out_time is not null ) ENTER2 ON f.fd_car_no = ENTER2.token_no ) enter3 WHERE enter3.in_status = '已出厂'
limit #{offset}, #{limit}
limit #{limit}
limit 5000
